import { test, expect } from '@playwright/test';

test.describe('404 Page Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://example.com'); // Replace with the actual base URL
  });

  test('should display 404 page for invalid URL', async ({ page }) => {
    await page.goto('http://example.com/invalid-url'); // Replace with an invalid URL
    const heading = await page.getByRole('heading', { name: /404 Not Found/i });
    await expect(heading).toBeVisible();
  });

  test('should have a link to go back to home on 404 page', async ({ page }) => {
    await page.goto('http://example.com/invalid-url'); // Replace with an invalid URL
    const homeLink = await page.getByRole('link', { name: /Home/i });
    await expect(homeLink).toBeVisible();
    await homeLink.click();
    await expect(page).toHaveURL('http://example.com/'); // Replace with the actual home URL
  });
});
